--
-- Table structure for table `dms_alert_log`
--

DROP TABLE IF EXISTS `dms_alert_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dms_alert_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `monitor_id` bigint DEFAULT NULL COMMENT 'monitor id',
  `task_id` bigint DEFAULT NULL COMMENT '任务ID',
  `stage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发预警的生产阶段',
  `alert_level` tinyint DEFAULT NULL COMMENT '等级：1预警 2告警 3严重',
  `alert_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型：TIMEOUT-超时, APPROACHING-即将超时',
  `alert_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'alert content',
  `notify_channels` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通知渠道：BOARD,PDA,WECHAT,SMS',
  `notify_targets` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通知对象ID列表',
  `is_resolved` tinyint DEFAULT NULL COMMENT '是否已处理: 0=否 1=是',
  `resolved_by` bigint DEFAULT NULL COMMENT '处理人',
  `resolved_at` datetime DEFAULT NULL COMMENT '解决时间',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_monitor_id` (`monitor_id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_alert_level` (`alert_level`),
  KEY `idx_is_resolved` (`is_resolved`),
  KEY `idx_al_resolved_monitor` (`is_resolved`,`monitor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=900001537 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='预警记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

