DROP TABLE IF EXISTS `md_department`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_department` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_id` varchar(64) DEFAULT NULL COMMENT '源库原始ID',
  `name` varchar(64) NOT NULL COMMENT '名称',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '父节点ID',
  `sort` int DEFAULT '0' COMMENT '排序',
  `leader` varchar(64) DEFAULT NULL COMMENT '负责人',
  `chairman` varchar(64) DEFAULT NULL COMMENT '主管',
  `deleted` bigint DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `tenant_id` varchar(64) DEFAULT 'default',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_id` (`source_id`),
  KEY `idx_parent` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='科室';
