DROP TABLE IF EXISTS `md_doctor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_doctor` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_id` varchar(64) DEFAULT NULL COMMENT '源库原始ID',
  `hospital_id` bigint DEFAULT NULL COMMENT '医院ID',
  `name` varchar(64) DEFAULT NULL COMMENT '姓名',
  `role` int DEFAULT NULL COMMENT '角色 1:医生 2:抓药师 3:药房员工',
  `sex` int DEFAULT NULL COMMENT '性别 1:男 2:女',
  `mobile` varchar(32) DEFAULT NULL COMMENT '联系电话',
  `department` varchar(64) DEFAULT NULL COMMENT '科室',
  `certificate_practice` varchar(64) DEFAULT NULL COMMENT '执业证书号',
  `phy_qualification` varchar(64) DEFAULT NULL COMMENT '医师资格证书号',
  `status` int DEFAULT '1' COMMENT '状态 1:有效 2:无效',
  `his_doctor_id` varchar(64) DEFAULT NULL COMMENT 'HIS系统医生编号',
  `deleted` bigint DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `tenant_id` varchar(64) DEFAULT 'default',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_source_id` (`source_id`),
  KEY `idx_hospital` (`hospital_id`),
  KEY `idx_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=2049 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='医生主数据';
