DROP TABLE IF EXISTS `md_drug`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_drug` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_id` varchar(64) DEFAULT NULL COMMENT '源库原始ID',
  `drug_type` varchar(32) DEFAULT NULL COMMENT '药品种类',
  `unit` varchar(32) DEFAULT NULL COMMENT '单位',
  `drug_name` varchar(255) DEFAULT NULL COMMENT '药品名称',
  `drug_specificat` varchar(255) DEFAULT NULL COMMENT '规格',
  `mnemonic` varchar(255) DEFAULT NULL COMMENT '助记符',
  `bas_material_id` varchar(64) DEFAULT NULL COMMENT '关联药房药品ID',
