DROP TABLE IF EXISTS `md_drug_footnote`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_drug_footnote` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `footnote_code` varchar(64) DEFAULT NULL COMMENT '编码',
  `footnote_name` varchar(255) NOT NULL COMMENT '名称',
  `sort` int DEFAULT '0' COMMENT '排序',
  `deleted` bigint DEFAULT '0' COMMENT '逻辑删除',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `tenant_id` varchar(64) DEFAULT 'default' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_footnote_name` (`footnote_name`)
) ENGINE=InnoDB AUTO_INCREMENT=257 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='药品脚注字典';
